// ============================================================
// NORMALIZE RETELL WEBHOOK DATA
// Converts Retell post-call webhook to standard format
// ============================================================

const body = $input.first().json.body || $input.first().json;

// Extract caller info
const caller = body.caller || {};
let phone = caller.phone || body.from_number || '';
// Normalize phone format
phone = phone.replace(/@s\.whatsapp\.net/g, '').replace(/^549/, '54').replace(/\D/g, '');

// Extract conversation data
const conversation = body.conversation || {};
const extractedData = body.extracted_data || {};
const aiMetadata = body.ai_metadata || {};

// Return normalized data
return {
  // Source tracking
  source: 'call',
  channel: 'retell',

  // Call metadata
  call_id: body.call_id || null,
  agent_id: body.agent_id || null,
  call_status: body.call_status || 'completed',
  call_duration: body.call_duration_seconds || 0,
  recording_url: body.recording_url || null,
  timestamp: body.timestamp || new Date().toISOString(),

  // Caller info
  phone: phone,
  name: caller.name || null,
  email: caller.email || null,

  // Conversation
  language: conversation.language || 'es',
  transcript: conversation.transcript || '',
  summary: conversation.summary || '',

  // Extracted intent data
  intent: extractedData.intent || null,
  property_type: extractedData.property_type || null,
  zone: extractedData.zone || null,
  urgency: extractedData.urgency || 'normal',
  retell_temperature: extractedData.lead_temperature || 'cold',
  budget: extractedData.budget || null,

  // AI metadata
  ai_model: aiMetadata.model || 'unknown',
  ai_confidence: aiMetadata.confidence_score || 0,

  // Keep raw for debugging
  _raw: body
};

// ============================================================
// LEAD SCORING ENGINE
// Calculates temperature (cold/warm/hot) and numeric score
// ============================================================

const data = $input.first().json;

let score = 0;
const reasons = [];

// ----- INTENT SCORING -----
const intent = (data.intent || '').toLowerCase();
if (intent === 'compra' || intent === 'buy' || intent === 'purchase') {
  score += 25;
  reasons.push('Intent: Purchase (+25)');
} else if (intent === 'alquiler' || intent === 'rent') {
  score += 15;
  reasons.push('Intent: Rent (+15)');
} else if (intent === 'venta' || intent === 'sell') {
  score += 20;
  reasons.push('Intent: Sell property (+20)');
}

// ----- URGENCY SCORING -----
const urgency = (data.urgency || '').toLowerCase();
if (urgency === 'alta' || urgency === 'high' || urgency === 'urgente') {
  score += 25;
  reasons.push('Urgency: High (+25)');
} else if (urgency === 'media' || urgency === 'medium') {
  score += 10;
  reasons.push('Urgency: Medium (+10)');
}

// ----- DATA COMPLETENESS -----
if (data.email) {
  score += 10;
  reasons.push('Has email (+10)');
}
if (data.name) {
  score += 5;
  reasons.push('Has name (+5)');
}
if (data.budget) {
  score += 10;
  reasons.push('Has budget (+10)');
}
if (data.zone) {
  score += 5;
  reasons.push('Has preferred zone (+5)');
}
if (data.property_type) {
  score += 5;
  reasons.push('Has property type (+5)');
}

// ----- CALL ENGAGEMENT -----
const duration = data.call_duration || 0;
if (duration > 180) {
  score += 15;
  reasons.push('Long call >3min (+15)');
} else if (duration > 60) {
  score += 5;
  reasons.push('Medium call >1min (+5)');
}

// ----- AI CONFIDENCE -----
if (data.ai_confidence > 0.8) {
  score += 5;
  reasons.push('High AI confidence (+5)');
}

// ----- RETELL CLASSIFICATION BOOST -----
const retellTemp = (data.retell_temperature || '').toLowerCase();
if (retellTemp === 'caliente' || retellTemp === 'hot') {
  score += 10;
  reasons.push('Retell: Hot (+10)');
} else if (retellTemp === 'tibio' || retellTemp === 'warm') {
  score += 5;
  reasons.push('Retell: Warm (+5)');
}

// ----- DETERMINE TEMPERATURE -----
let temperature = 'cold';
if (score >= 60) {
  temperature = 'hot';
} else if (score >= 30) {
  temperature = 'warm';
}

// Cap score
score = Math.min(score, 100);

return {
  ...data,
  score: score,
  temperature: temperature,
  scoring_reasons: reasons
};

// ============================================================
// PREPARE CRM PAYLOAD FOR GOHIGHLEVEL
// ============================================================

const scored = $('Score Lead').first().json;
const dbLead = $input.first().json;
const interaction = $('DB - Log Call').first().json;

// Build name parts
const nameParts = (scored.name || '').split(' ');
const firstName = nameParts[0] || '';
const lastName = nameParts.slice(1).join(' ') || '';

// Build tags
const tags = [
  `temperature:${scored.temperature}`,
  `score:${scored.score}`,
  scored.intent ? `intent:${scored.intent}` : null,
  'source:retell-call'
].filter(Boolean);

// Build custom fields
const customFields = [
  { key: 'lead_temperature', value: scored.temperature },
  { key: 'lead_score', value: String(scored.score) },
  { key: 'property_intent', value: scored.intent || 'unknown' },
  { key: 'preferred_zone', value: scored.zone || '' },
  { key: 'budget', value: scored.budget ? String(scored.budget) : '' },
  { key: 'call_summary', value: (scored.summary || '').substring(0, 500) },
  { key: 'last_interaction_date', value: new Date().toISOString().split('T')[0] }
];

return {
  // Lead data
  lead_id: dbLead.id,
  phone: scored.phone,
  temperature: scored.temperature,
  score: scored.score,
  existing_crm_id: dbLead.crm_id,

  // GHL payload
  ghl: {
    firstName: firstName,
    lastName: lastName,
    phone: scored.phone,
    email: scored.email || '',
    source: 'Retell AI Call',
    tags: tags,
    customFields: customFields
  },

  // For notes
  call_summary: scored.summary,
  call_duration: scored.call_duration,
  recording_url: scored.recording_url,
  scoring_reasons: scored.scoring_reasons,
  interaction_id: interaction.id
};

